#!/usr/bin/env python3
"""Compatibility for upstream's game/native-mod layout.

Called by sync-upstream.yml only when the synced tree has no
crates/horizon-client/src/main.rs and does have crates/horizon-game/src/main.rs.
The launcher itself is still the fork's: it supports mods pinned to older
revisions, so the old generated main stays for those stages.
"""

from pathlib import Path

ROOT = Path.cwd()
API = ROOT / "launcher/src/native_mods/api.rs"
GAME_WORKFLOW = ROOT / ".github/workflows/game.yml"


def replace_once(text: str, old: str, new: str, what: str) -> str:
    if old not in text:
        raise SystemExit(f"cannot adapt {what}: source text not found")
    return text.replace(old, new, 1)


def main() -> None:
    shader_api = ROOT / "crates/horizon-shader-api/src/manifest.rs"
    if 'pub const API: &str = "0.2"' in shader_api.read_text():
        text = shader_api.read_text()
        old = "        if raw.api != API {\n"
        new = """        // The offline launcher still reads shader packs made for the 0.1 API.
        if raw.api != API && raw.api != "0.1" {
"""
        if old in text:
            shader_api.write_text(text.replace(old, new, 1))
        # The registry fixture pins a shader version to the API it listed before. The served API
        # is what a file's facts report now, so the index must name the same line.
        index = ROOT / "crates/horizon-mods/tests/index/index-v1.json"
        entries = index.read_text()
        glow = entries.index('"id": "glow"')
        if '"api": "0.1"' in entries[glow:]:
            listed = entries.index('"api": "0.1"', glow)
            entries = entries[:listed] + '"api": "0.2"' + entries[listed + len('"api": "0.1"'):]
            index.write_text(entries)

    if (ROOT / "crates/horizon-client/src/main.rs").is_file():
        return
    if not (ROOT / "crates/horizon-game/src/main.rs").is_file():
        return

    source = API.read_text()
    if "fn main_rs_upstream" in source:
        return
    marker = "/// API objects in the same order as the generated executable's mod list."
    added = '''/// Whether a staged revision uses upstream's game and native-mod layout.
fn upstream_layout(stage: &Path) -> bool {
    stage.join("crates/horizon-game/src/main.rs").is_file()
}

/// The executable built for that layout: the allocator belongs to the client library,
/// and the mod host starts the game with the mod entries.
fn main_rs_upstream(ids: &[&str]) -> String {
    let entries = ids
        .iter()
        .enumerate()
        .map(|(i, id)| {
            format!("        mod_api::ModEntry::new({:?}, Box::new(mod_{i}::hooks())),\\n", id)
        })
        .collect::<String>();
    format!(
        r##"//! Generated by the launcher.
#![forbid(unsafe_code)]

static MOD_API_LEVEL: [u8; horizon_mods::api_level::MARK.len()] = horizon_mods::api_level::MARK;

fn main() {{
    horizon_guest_stack::run_main(|| {{
        std::hint::black_box(&MOD_API_LEVEL);
        horizon_game::give_menu_look();
        let startup = horizon_client::entry::prepare();
        let mods: Vec<mod_api::ModEntry> = vec![
{entries}            ];
        horizon_mod_host::main_with(mods, &[], &[], startup);
    }});
}}
"##
    )
}

'''
    source = replace_once(source, marker, added + marker, "api.rs generated main")

    old = '''    for name in ["horizon-client", "horizon-threads", "horizon-mods"] {
        deps.insert(name.into(), path_dep(&format!("../{name}")));
    }
'''
    new = old + '''
    if upstream_layout(stage) {
        deps.insert("horizon-game".into(), path_dep("../horizon-game"));
        deps.insert("horizon-guest-stack".into(), path_dep("../horizon-guest-stack"));
        deps.insert("horizon-mod-host".into(), path_dep("../horizon-mod-host"));
        deps.insert(
            "mod_api".into(),
            toml::Value::Table(toml::Table::from_iter([
                ("package".into(), "horizon-mod-api".into()),
                ("path".into(), "../horizon-mod-api".into()),
            ])),
        );
    }
'''
    source = replace_once(source, old, new, "api.rs generated dependencies")

    old = '''    fs::write(game.join("src/main.rs"), main_rs(&ids, names_mods(stage)))
        .map_err(|e| e.to_string())?;
'''
    new = '''    let generated = if upstream_layout(stage) {
        main_rs_upstream(&ids)
    } else {
        main_rs(&ids, names_mods(stage))
    };
    fs::write(game.join("src/main.rs"), generated).map_err(|e| e.to_string())?;
'''
    source = replace_once(source, old, new, "api.rs staged main")

    old = '''    #[test]
    fn generated_main_uses_the_games_allocator() {
        let game = include_str!("../../../crates/horizon-client/src/main.rs");
        let allocator = game
            .lines()
            .find(|line| line.starts_with("static ALLOCATOR:"))
            .unwrap();
        let generated = main_rs(&[], false);
        assert!(generated.lines().any(|line| line == allocator));
    }
'''
    new = '''    #[test]
    fn generated_main_uses_the_games_allocator() {
        let root = Path::new(env!("CARGO_MANIFEST_DIR")).join("..");
        if upstream_layout(&root) {
            let game = fs::read_to_string(root.join("crates/horizon-client/src/lib.rs")).unwrap();
            let allocator = game
                .lines()
                .find(|line| line.starts_with("static ALLOCATOR:"))
                .unwrap();
            // The library owns the allocator now; a second one in the executable would clash.
            assert!(allocator.contains("GameAllocator"));
            assert!(!main_rs_upstream(&[]).contains("#[global_allocator]"));
        } else {
            let game =
                fs::read_to_string(root.join("crates/horizon-client/src/main.rs")).unwrap();
            let allocator = game
                .lines()
                .find(|line| line.starts_with("static ALLOCATOR:"))
                .unwrap();
            let generated = main_rs(&[], false);
            assert!(generated.lines().any(|line| line == allocator));
        }
    }

    #[test]
    fn upstream_main_keeps_mod_order() {
        let ids = ["base", "extra"];
        let text = main_rs_upstream(&ids);
        assert!(text.contains("horizon_mod_host::main_with(mods, &[], &[], startup)"));
        assert_eq!(text.matches("::hooks()").count(), 2);
        assert!(text.find("mod_0::hooks()").unwrap() < text.find("mod_1::hooks()").unwrap());
        assert!(text.contains("ModEntry::new(\\"base\\""));
        assert!(text.contains("ModEntry::new(\\"extra\\""));
    }
'''
    source = replace_once(source, old, new, "api.rs allocator test")
    API.write_text(source)

    workflow = GAME_WORKFLOW.read_text()
    workflow = replace_once(
        workflow,
        "-p horizon-client --bin horizon-client",
        "-p horizon-game --bin horizon-client",
        "game workflow's executable",
    )
    GAME_WORKFLOW.write_text(workflow)


if __name__ == "__main__":
    main()
